import{_ as o,C as a,o as n,c as r,j as t,a as s,G as l,a3 as h}from"./chunks/framework.Bvm_liKL.js";const w=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/troubleshooting.md","filePath":"en/guide/troubleshooting.md"}'),p={name:"en/guide/troubleshooting.md"};function c(u,e,d,g,m,f){const i=a("ArticleMetadata");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"troubleshooting",tabindex:"-1"},[s("Troubleshooting "),t("a",{class:"header-anchor",href:"#troubleshooting","aria-label":'Permalink to "Troubleshooting"'},"​")],-1)),l(i),e[1]||(e[1]=h('<blockquote><p>Encountered an issue? Here are the solutions to common problems:</p></blockquote><h2 id="startup-issues" tabindex="-1">Startup Issues <a class="header-anchor" href="#startup-issues" aria-label="Permalink to &quot;Startup Issues&quot;">​</a></h2><h3 id="the-application-cannot-start" tabindex="-1">The application cannot start <a class="header-anchor" href="#the-application-cannot-start" aria-label="Permalink to &quot;The application cannot start&quot;">​</a></h3><p><strong>Symptom</strong>: Double-clicking the application icon has no response, or an error message appears.</p><p><strong>Solutions</strong>:</p><ol><li>Ensure you have installed the required version of .NET Framework.</li><li>Run the application as an administrator.</li><li>Check the Windows Event Viewer for error logs.</li><li>Try extracting the zip archive to a different path (avoid using protected system folders).</li></ol><h3 id="no-interface-visible-after-startup" tabindex="-1">No interface visible after startup <a class="header-anchor" href="#no-interface-visible-after-startup" aria-label="Permalink to &quot;No interface visible after startup&quot;">​</a></h3><p><strong>Symptom</strong>: The application seems to have launched (visible in Task Manager), but there is no visible interface.</p><p><strong>Solutions</strong>:</p><ol><li>Check if there is an ICC-CE icon in the system tray.</li><li>Try pressing Alt+Tab to switch to the application.</li><li>Right-click the application icon in the taskbar and select &quot;Maximize&quot;.</li><li>Reset application settings (delete the <code>%AppData%\\ICC-CE</code> folder).</li></ol><h2 id="drawing-issues" tabindex="-1">Drawing Issues <a class="header-anchor" href="#drawing-issues" aria-label="Permalink to &quot;Drawing Issues&quot;">​</a></h2><h3 id="ink-is-not-showing" tabindex="-1">Ink is not showing <a class="header-anchor" href="#ink-is-not-showing" aria-label="Permalink to &quot;Ink is not showing&quot;">​</a></h3><p><strong>Symptom</strong>: Drawing on the screen but no strokes appear.</p><p><strong>Solutions</strong>:</p><ol><li>Make sure you haven&#39;t accidentally selected a transparent color.</li><li>Check if the current layer is set to visible.</li><li>Try switching drawing modes.</li><li>Restart the application.</li></ol><h3 id="line-straightening-is-not-working" tabindex="-1">Line straightening is not working <a class="header-anchor" href="#line-straightening-is-not-working" aria-label="Permalink to &quot;Line straightening is not working&quot;">​</a></h3><p><strong>Symptom</strong>: The line straightening function does not work or behaves inconsistently.</p><p><strong>Solutions</strong>:</p><ol><li>Verify that auto-straightening is enabled in Settings.</li><li>Adjust the sensitivity setting - try a higher value (0.5-1.5).</li><li>Ensure the length of the drawn line exceeds the set threshold.</li><li>Keep the drawing speed relatively steady.</li><li>Check if other drawing configurations are conflicting.</li></ol><h3 id="touch-input-issues" tabindex="-1">Touch input issues <a class="header-anchor" href="#touch-input-issues" aria-label="Permalink to &quot;Touch input issues&quot;">​</a></h3><p><strong>Symptom</strong>: Touchscreen inputs are imprecise or not recognized.</p><p><strong>Solutions</strong>:</p><ol><li>Adjust the touch multiplier setting.</li><li>Enable or disable nib mode.</li><li>Increase the finger mode boundary width.</li><li>Ensure Windows Touch Settings are functioning normally.</li><li>Check Device Manager to ensure your touchscreen drivers are up-to-date.</li></ol><h2 id="powerpoint-integration-issues" tabindex="-1">PowerPoint Integration Issues <a class="header-anchor" href="#powerpoint-integration-issues" aria-label="Permalink to &quot;PowerPoint Integration Issues&quot;">​</a></h2><h3 id="cannot-detect-powerpoint" tabindex="-1">Cannot detect PowerPoint <a class="header-anchor" href="#cannot-detect-powerpoint" aria-label="Permalink to &quot;Cannot detect PowerPoint&quot;">​</a></h3><p><strong>Symptom</strong>: No ICC-CE integration features appear during PowerPoint slideshows.</p><p><strong>Solutions</strong>:</p><ol><li>Confirm that PowerPoint support is enabled in Settings.</li><li>Use a compatible version of PowerPoint (2016 or higher).</li><li>Start ICC-CE before starting PowerPoint.</li><li>Check if other software is blocking the PowerPoint COM integration.</li></ol><h3 id="drawing-lag-in-powerpoint" tabindex="-1">Drawing lag in PowerPoint <a class="header-anchor" href="#drawing-lag-in-powerpoint" aria-label="Permalink to &quot;Drawing lag in PowerPoint&quot;">​</a></h3><p><strong>Symptom</strong>: Obvious delay when drawing in PowerPoint slideshow mode.</p><p><strong>Solutions</strong>:</p><ol><li>Lower the transparency of the ICC-CE toolbar in PowerPoint.</li><li>Turn off unnecessary PowerPoint slide transition animations.</li><li>Ensure the computer meets the system requirements.</li><li>Close other resource-intensive applications.</li></ol><h2 id="performance-issues" tabindex="-1">Performance Issues <a class="header-anchor" href="#performance-issues" aria-label="Permalink to &quot;Performance Issues&quot;">​</a></h2><h3 id="the-application-runs-slowly" tabindex="-1">The application runs slowly <a class="header-anchor" href="#the-application-runs-slowly" aria-label="Permalink to &quot;The application runs slowly&quot;">​</a></h3><p><strong>Symptom</strong>: Laggy interface response or delay when drawing.</p><p><strong>Solutions</strong>:</p><ol><li>Clear old ink files and auto-saved screenshots.</li><li>Disable unnecessary automation features.</li><li>Reduce UI transparency.</li><li>Enable performance optimization options in Settings.</li></ol><h3 id="high-memory-usage" tabindex="-1">High memory usage <a class="header-anchor" href="#high-memory-usage" aria-label="Permalink to &quot;High memory usage&quot;">​</a></h3><p><strong>Symptom</strong>: The application consumes a large amount of memory or increases over time.</p><p><strong>Solutions</strong>:</p><ol><li>Periodically clear the canvas.</li><li>Reduce the number of active ink strokes.</li><li>Enable automatic cleanup of old files.</li><li>Restart the application to release memory.</li></ol><h2 id="resetting-the-application" tabindex="-1">Resetting the Application <a class="header-anchor" href="#resetting-the-application" aria-label="Permalink to &quot;Resetting the Application&quot;">​</a></h2><p>If you encounter persistent issues, you can try resetting the application:</p><ol><li>Close the ICC-CE application.</li><li>Navigate to the <code>%AppData%\\ICC-CE</code> folder.</li><li>Back up the <code>settings.json</code> file (if you wish to preserve your settings).</li><li>Delete all files in the folder.</li><li>Restart ICC-CE.</li></ol><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Resetting the application will delete all custom settings and preferences.</p></div><h2 id="contact-support" tabindex="-1">Contact Support <a class="header-anchor" href="#contact-support" aria-label="Permalink to &quot;Contact Support&quot;">​</a></h2><p>If the above methods do not resolve your issue:</p><ol><li>Submit an issue on <a href="https://github.com/InkCanvasForClass/community/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</li><li>Provide a detailed description of the problem and steps to reproduce.</li><li>Attach log files (if logging is enabled).</li><li>State your system configuration and ICC-CE version.</li></ol>',48))])}const y=o(p,[["render",c]]);export{w as __pageData,y as default};
